use super::*;

impl Backend{
pub(super) async fn read_work_detail(&mut self,conversation_id:String,work_id:String)->Result<()>{let value=self.client()?.read(ReadRequest::Work{conversation_id:conversation_id.clone(),work_id:work_id.clone()}).await?;let network=self.client()?.network_id().to_owned();let detail=crate::views::records::parse_work_detail(value,&network,&conversation_id,&work_id)?;let target=detail.work.target.clone();self.state.work_detail=Some(Arc::new(detail));if let Some(InputTarget::Task{task_id}|InputTarget::ChannelTask{task_id,..})=&target{let channel_id=match &target{Some(InputTarget::ChannelTask{channel_id,..})=>Some(channel_id.clone()),_=>None};let history=self.client()?.read(ReadRequest::WorkspaceHistory{channel_id:channel_id.clone(),task_id:Some(task_id.clone()),limit:100}).await;match history.and_then(|value|crate::views::records::parse_workspace_history(value,&network,channel_id.as_deref(),Some(task_id.as_str()),&self.history_bindings())){Ok(history)=>self.state.channel_history=Some(Arc::new(history)),Err(error)=>{let _=self.out.send(Event::Notice(format!("工作详情已读取，原始附件历史暂不可读：{error}"))).await;}}}if self.conversation.as_ref()!=Some(&conversation_id){self.conversation=Some(conversation_id);self.refresh().await?;}else{self.publish();}Ok(())}
pub(super) async fn read_history(&mut self,channel_id:Option<String>,task_id:Option<String>)->Result<()>{let value=self.client()?.read(ReadRequest::WorkspaceHistory{channel_id:channel_id.clone(),task_id:task_id.clone(),limit:100}).await?;let network=self.client()?.network_id().to_owned();let bindings=self.history_bindings();let history=crate::views::records::parse_workspace_history(value,&network,channel_id.as_deref(),task_id.as_deref(),&bindings)?;self.state.channel_history=Some(Arc::new(history));self.publish();Ok(())}
pub(super) async fn refresh_active_record(&mut self)->Result<()>{if !self.state.online{return Ok(())}self.last_record_read=tokio::time::Instant::now();match self.active_record.clone(){ActiveRecord::None=>{},ActiveRecord::Work{conversation_id,work_id}=>self.read_work_detail(conversation_id,work_id).await?,ActiveRecord::Channel(channel_id)=>self.read_history(Some(channel_id),None).await?,ActiveRecord::Task(task_id)=>self.read_history(None,Some(task_id)).await?,}Ok(())}

}
